# Build mapping from note_id to group_id based on title match
note_id_to_group_id = {}
for note_id in note_ids:
    title = note_contents[note_id].split('\n')[0].lstrip('# ').strip()
    # Find matching group
    for g in trip_groups:
        if g['name'] == title:
            note_id_to_group_id[note_id] = g['group_id']
            break

print(note_id_to_group_id)

