steps.code:
# Build mapping of group_id to first_name -> email
group_member_map = {}
for g in trip_groups:
    gid = g['group_id']
    name_to_email = {}
    for m in g['members']:
        # Extract first name from full name
        first = m['name'].split()[0]
        name_to_email[first] = m['email']
    group_member_map[gid] = name_to_email

# Test for Moscow group (275)
print(group_member_map[275])

